import{_ as a}from"./chunks/plugin-vue_export-helper.DlAUqK2U.js";import{B as r,c as s,f as e,q as d,D as o,Q as p,g as l}from"./chunks/runtime-core.esm-bundler.BPXnTuTE.js";const x=JSON.parse('{"title":"npm / yarn / pnpm 完整对比总结","description":"","frontmatter":{},"headers":[],"relativePath":"column/Node/基础/npm-yarn-pnpm 对比.md","filePath":"column/Node/基础/npm-yarn-pnpm 对比.md","lastUpdated":1787557243000}'),i={name:"column/Node/基础/npm-yarn-pnpm 对比.md"};function c(h,t,m,g,b,k){const n=r("ArticleMetadata");return e(),s("div",null,[t[0]||(t[0]=d("h1",{id:"npm-yarn-pnpm-完整对比总结",tabindex:"-1"},[l("npm / yarn / pnpm 完整对比总结 "),d("a",{class:"header-anchor",href:"#npm-yarn-pnpm-完整对比总结","aria-label":'Permalink to "npm / yarn / pnpm 完整对比总结"'},"​")],-1)),o(n),t[1]||(t[1]=p(`<p>目前 <code>JavaScript</code> 生态中最主流的三个包管理器是 <strong>npm</strong>、<strong>yarn</strong> 和 <strong>pnpm</strong>。它们都能完成安装依赖、管理版本、运行脚本等基础工作，但在存储方式、安装速度、磁盘占用、依赖严格性等方面差异明显。</p><h3 id="一、基本信息" tabindex="-1">一、基本信息 <a class="header-anchor" href="#一、基本信息" aria-label="Permalink to &quot;一、基本信息&quot;">​</a></h3><table tabindex="0"><thead><tr><th>对比项</th><th>npm</th><th>yarn</th><th>pnpm</th></tr></thead><tbody><tr><td>诞生时间</td><td>2010</td><td>2016</td><td>2017</td></tr><tr><td>是否随 Node 自带</td><td>✅ 是</td><td>❌ 否</td><td>❌ 否</td></tr><tr><td>锁文件</td><td><code>package-lock.json</code></td><td><code>yarn.lock</code></td><td><code>pnpm-lock.yaml</code></td></tr><tr><td>当前主流版本</td><td>npm 10 / 11</td><td>yarn Berry (v2~v4)</td><td>pnpm 9 / 10 / 11</td></tr><tr><td>核心理念</td><td>简单、兼容性优先</td><td>速度 + 确定性 + 插件</td><td>省空间 + 严格 + 快速</td></tr></tbody></table><blockquote><p>注：yarn 分为 <strong>Classic（v1）</strong> 和 <strong>Berry（v2+）</strong>。现在讨论的优势大多指 Berry，尤其是其 Plug’n’Play（PnP）模式。</p></blockquote><h3 id="二、核心差异-存储与链接方式" tabindex="-1">二、核心差异：存储与链接方式 <a class="header-anchor" href="#二、核心差异-存储与链接方式" aria-label="Permalink to &quot;二、核心差异：存储与链接方式&quot;">​</a></h3><table tabindex="0"><thead><tr><th>包管理器</th><th>存储方式</th><th>说明</th></tr></thead><tbody><tr><td><strong>npm</strong></td><td>每个项目独立复制</td><td>同一个包在不同项目中会完整复制多份</td></tr><tr><td><strong>yarn Classic</strong></td><td>每个项目独立复制 + 全局缓存</td><td>和 npm 类似，有缓存加速</td></tr><tr><td><strong>yarn Berry (PnP)</strong></td><td>几乎无 <code>node_modules</code></td><td>用 <code>.pnp.cjs</code> 映射，实现零安装</td></tr><tr><td><strong>pnpm</strong></td><td><strong>全局内容寻址存储 + 硬链接</strong></td><td>所有项目共享同一份文件，通过硬链接引用</td></tr></tbody></table><p><strong>pnpm 的核心优势</strong>：</p><ul><li>相同内容的文件在磁盘上只存一份</li><li>项目通过硬链接引用，几乎不占额外空间</li><li>多项目场景下磁盘占用可减少 50%~80%</li></ul><h3 id="三、多维度详细对比" tabindex="-1">三、多维度详细对比 <a class="header-anchor" href="#三、多维度详细对比" aria-label="Permalink to &quot;三、多维度详细对比&quot;">​</a></h3><table tabindex="0"><thead><tr><th>维度</th><th>npm</th><th>yarn</th><th>pnpm</th><th>优胜者</th></tr></thead><tbody><tr><td><strong>安装速度</strong></td><td>中等（已改善）</td><td>快（并行下载）</td><td><strong>最快</strong>（硬链接）</td><td>pnpm</td></tr><tr><td><strong>磁盘占用</strong></td><td>高（重复复制）</td><td>中高 / PnP 很低</td><td><strong>极低</strong></td><td>pnpm</td></tr><tr><td><strong>幽灵依赖</strong></td><td>存在</td><td>Classic 存在，PnP 不存在</td><td><strong>严格杜绝</strong></td><td>pnpm</td></tr><tr><td><strong>依赖隔离</strong></td><td>弱（扁平化提升）</td><td>中等 / PnP 强</td><td><strong>强</strong></td><td>pnpm</td></tr><tr><td><strong>Monorepo 支持</strong></td><td>有（workspaces）</td><td>优秀</td><td><strong>优秀</strong></td><td>yarn / pnpm</td></tr><tr><td><strong>生态兼容性</strong></td><td><strong>最好</strong></td><td>很好（PnP 需适配）</td><td>很好（极少问题）</td><td>npm</td></tr><tr><td><strong>学习成本</strong></td><td>最低</td><td>中等</td><td>较低</td><td>npm</td></tr><tr><td><strong>Zero-Installs</strong></td><td>❌</td><td>✅（Berry PnP）</td><td>❌</td><td>yarn</td></tr><tr><td><strong>依赖补丁</strong></td><td>❌</td><td>✅</td><td>✅</td><td>yarn / pnpm</td></tr><tr><td><strong>对等依赖自动安装</strong></td><td>✅</td><td>❌</td><td>✅</td><td>npm / pnpm</td></tr><tr><td><strong>管理 Node 版本</strong></td><td>❌</td><td>❌</td><td>✅</td><td>pnpm</td></tr></tbody></table><h3 id="四、什么是幽灵依赖" tabindex="-1">四、什么是幽灵依赖？ <a class="header-anchor" href="#四、什么是幽灵依赖" aria-label="Permalink to &quot;四、什么是幽灵依赖？&quot;">​</a></h3><p><strong>幽灵依赖（Phantom Dependencies）</strong>：代码里可以 <code>import</code> 一个没有在 <code>package.json</code> 中声明的包。</p><p>原因是 npm / yarn Classic 会把间接依赖提升到 <code>node_modules</code> 顶层。</p><p><strong>危害</strong>：</p><ul><li>本地能跑，换环境或依赖升级后可能突然报错</li><li>依赖关系不清晰，不利于维护</li></ul><p><strong>pnpm</strong> 通过非扁平的严格结构，从根源上阻止了这个问题——只有你明确声明的依赖才能被访问。</p><h3 id="五、常用命令对照" tabindex="-1">五、常用命令对照 <a class="header-anchor" href="#五、常用命令对照" aria-label="Permalink to &quot;五、常用命令对照&quot;">​</a></h3><table tabindex="0"><thead><tr><th>操作</th><th>npm</th><th>yarn</th><th>pnpm</th></tr></thead><tbody><tr><td>安装全部依赖</td><td><code>npm install</code></td><td><code>yarn</code> / <code>yarn install</code></td><td><code>pnpm install</code></td></tr><tr><td>添加依赖</td><td><code>npm install lodash</code></td><td><code>yarn add lodash</code></td><td><code>pnpm add lodash</code></td></tr><tr><td>添加开发依赖</td><td><code>npm i -D xxx</code></td><td><code>yarn add -D xxx</code></td><td><code>pnpm add -D xxx</code></td></tr><tr><td>删除依赖</td><td><code>npm uninstall xxx</code></td><td><code>yarn remove xxx</code></td><td><code>pnpm remove xxx</code></td></tr><tr><td>执行临时包</td><td><code>npx xxx</code></td><td><code>yarn dlx xxx</code></td><td><code>pnpm dlx xxx</code></td></tr><tr><td>运行脚本</td><td><code>npm run dev</code></td><td><code>yarn dev</code></td><td><code>pnpm dev</code></td></tr><tr><td>更新依赖</td><td><code>npm update</code></td><td><code>yarn up</code></td><td><code>pnpm update</code></td></tr><tr><td>CI 严格安装</td><td><code>npm ci</code></td><td><code>yarn install --immutable</code></td><td><code>pnpm install --frozen-lockfile</code></td></tr></tbody></table><h3 id="六、其他重要细节" tabindex="-1">六、其他重要细节 <a class="header-anchor" href="#六、其他重要细节" aria-label="Permalink to &quot;六、其他重要细节&quot;">​</a></h3><p><strong>1. Corepack（推荐使用）</strong> Node.js 自带的包管理器管理工具，可统一管理 npm / yarn / pnpm 的版本：</p><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">corepack</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> enable</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">corepack</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> prepare</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pnpm@latest</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --activate</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p><strong>2. 安全相关</strong></p><ul><li>三者都支持审计（audit）和完整性校验</li><li>pnpm 支持 <code>minimumReleaseAge</code>（只安装发布一段时间后的包，降低供应链风险）</li><li>yarn Berry 默认对 postinstall 脚本更谨慎</li></ul><p><strong>3. 离线安装</strong></p><ul><li>npm：<code>npm ci</code></li><li>yarn：<code>yarn install --offline</code></li><li>pnpm：<code>pnpm install --offline</code></li></ul><h3 id="七、适用场景建议" tabindex="-1">七、适用场景建议 <a class="header-anchor" href="#七、适用场景建议" aria-label="Permalink to &quot;七、适用场景建议&quot;">​</a></h3><table tabindex="0"><thead><tr><th>场景</th><th>推荐选择</th><th>原因</th></tr></thead><tbody><tr><td>新手学习 / 小项目</td><td><strong>npm</strong></td><td>自带，零配置，兼容性最好</td></tr><tr><td>个人多项目开发</td><td><strong>pnpm</strong></td><td>省磁盘、安装快、严格依赖</td></tr><tr><td>中大型项目 / 团队</td><td><strong>pnpm</strong></td><td>速度快 + 省空间 + 避免幽灵依赖</td></tr><tr><td>大型 Monorepo</td><td><strong>pnpm</strong> 或 <strong>yarn Berry</strong></td><td>两者 workspaces 都很强</td></tr><tr><td>追求极致兼容 / 老项目</td><td><strong>npm</strong></td><td>兼容性最稳</td></tr><tr><td>喜欢插件生态 / 零安装</td><td><strong>yarn Berry (PnP)</strong></td><td>功能丰富，支持 Zero-Installs</td></tr></tbody></table><h3 id="八、迁移建议-以-npm-→-pnpm-为例" tabindex="-1">八、迁移建议（以 npm → pnpm 为例） <a class="header-anchor" href="#八、迁移建议-以-npm-→-pnpm-为例" aria-label="Permalink to &quot;八、迁移建议（以 npm → pnpm 为例）&quot;">​</a></h3><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 启用 corepack</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">corepack</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> enable</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 安装并使用 pnpm</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 删除旧的 lock 文件</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">rm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> package-lock.json</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br></div></div><p>大多数项目几乎无痛切换，只有极少数依赖扁平结构的老包可能需要微调。</p><h3 id="九、一句话总结" tabindex="-1">九、一句话总结 <a class="header-anchor" href="#九、一句话总结" aria-label="Permalink to &quot;九、一句话总结&quot;">​</a></h3><ul><li><strong>npm</strong>：官方默认，最稳最省心，适合入门和追求兼容的场景。</li><li><strong>yarn</strong>：曾经解决了 npm 的速度和确定性问题，现在 Berry 版本功能强大，尤其适合喜欢插件和 PnP 的团队。</li><li><strong>pnpm</strong>：目前综合表现最均衡，<strong>省空间、速度快、依赖严格</strong>，是 2025~2026 年很多新项目的首选。</li></ul><p><strong>当前趋势</strong>：新项目越来越多默认选择 <strong>pnpm</strong>，npm 继续作为兜底方案存在，yarn 则在 monorepo 和特定团队中保持影响力。</p>`,33))])}const P=a(i,[["render",c]]);export{x as __pageData,P as default};
